20	import { createChart, getGraphicElements } from '../../../core/utHelper';
21	import { EChartsType } from '../../../../../src/echarts';
22	import { EChartsOption } from '../../../../../src/export/option';
23	import { CalendarOption } from '../../../../../src/coord/calendar/CalendarModel';
24	import Element from 'zrender/src/Element';
25	import ZRText from 'zrender/src/graphic/Text';
26	
27	function makeOption(calendarOption: CalendarOption): EChartsOption {
28	    return {
29	        calendar: [calendarOption],
30	        series: []
31	    } as EChartsOption;
32	}
33	
34	/**
35	 * Texts are created by `CalendarView` in this order:
36	 * year text (1), month texts (n), day texts (7).
37	 */
38	function getLabelTexts(chart: EChartsType) {
39	    const texts = getGraphicElements(chart, 'calendar').filter(
40	        el => el instanceof ZRText
41	    ) as ZRText[];
42	    const dayTexts = texts.slice(texts.length - 7);
43	    const yearTexts = texts.slice(0, 1);
44	    const monthTexts = texts.slice(1, texts.length - 7);
45	    return { yearTexts, monthTexts, dayTexts };
46	}
47	
48	function silentOf(els: Element[]) {
49	    return els.map(el => !!el.silent);
50	}
51	
52	describe('calendar_labelSilent', function () {
53	    let chart: EChartsType;
54	    beforeEach(function () {
55	        chart = createChart({ width: 600, height: 500 });
56	    });
57	
58	    afterEach(function () {
59	        chart.dispose();
60	    });
61	
62	    it('should not be silent by default', function () {
63	        chart.setOption(makeOption({
64	            range: '2017-02'
65	        }));
66	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
67	        expect(yearTexts.length).toBe(1);
68	        expect(monthTexts.length).toBeGreaterThan(0);
69	        expect(dayTexts.length).toBe(7);
70	        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
71	        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
72	        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
73	    });
74	
75	    it('dayLabel.silent should only silence day labels', function () {
76	        chart.setOption(makeOption({
77	            range: '2017-02',
78	            dayLabel: { silent: true }
79	        }));
80	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
81	        expect(silentOf(dayTexts).indexOf(false)).toBe(-1);
82	        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
83	        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
84	    });
85	
86	    it('monthLabel.silent should only silence month labels', function () {
87	        chart.setOption(makeOption({
88	            range: '2017-02',
89	            monthLabel: { silent: true }
90	        }));
91	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
92	        expect(silentOf(monthTexts).indexOf(false)).toBe(-1);
93	        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
94	        expect(silentOf(yearTexts).indexOf(true)).toBe(-1);
95	    });
96	
97	    it('yearLabel.silent should only silence the year label', function () {
98	        chart.setOption(makeOption({
99	            range: '2017-02',
100	            yearLabel: { silent: true }
101	        }));
102	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
103	        expect(silentOf(yearTexts).indexOf(false)).toBe(-1);
104	        expect(silentOf(monthTexts).indexOf(true)).toBe(-1);
105	        expect(silentOf(dayTexts).indexOf(true)).toBe(-1);
106	    });
107	
108	    it('silent: false should keep labels interactive and visible', function () {
109	        chart.setOption(makeOption({
110	            range: '2017-02',
111	            dayLabel: { silent: false },
112	            monthLabel: { silent: false },
113	            yearLabel: { silent: false }
114	        }));
115	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
116	        const all = ([] as Element[]).concat(yearTexts, monthTexts, dayTexts);
117	        expect(silentOf(all).indexOf(true)).toBe(-1);
118	        // Visuals are preserved.
119	        expect((dayTexts[0].style.text as string).length).toBeGreaterThan(0);
120	        expect((yearTexts[0].style.text as string).length).toBeGreaterThan(0);
121	    });
122	
123	    it('all three can be silenced together', function () {
124	        chart.setOption(makeOption({
125	            range: '2017-02',
126	            dayLabel: { silent: true },
127	            monthLabel: { silent: true },
128	            yearLabel: { silent: true }
129	        }));
130	        const { yearTexts, monthTexts, dayTexts } = getLabelTexts(chart);
131	        const all = ([] as Element[]).concat(yearTexts, monthTexts, dayTexts);
132	        expect(silentOf(all).indexOf(false)).toBe(-1);
133	    });
134	});
